always @(posedge clk or negedge nReset)
  if (~nReset)
    cmd_stop <= #1 1'b0;
  else if (rst)
    cmd_stop <= #1 1'b0;

always @(posedge clk or negedge nReset)
  if (~nReset)
    al <= #1 1'b0;
  else if (rst)
    al <= #1 1'b0;
  else
    al <= #1 ~cmd_stop;

	always @(posedge clk)
	  if (~|cnt)
	    if (~slave_wait)
	      begin
	          cnt    <= #1 clk_cnt;
	          clk_en <= #1 1'b1;
	      end
	    else
	      begin
	          cnt    <= #1 cnt;
	          clk_en <= #1 1'b0;
	      end
	  else
	    begin
                cnt    <= #1 cnt - 16'h1;
	        clk_en <= #1 1'b0;
	    end
